// 1. Ambil data SHEET (History Lengkap)
// Karena sekarang di belakang Merge, $input.all() isinya adalah hasil bacaan Get Row
const rows = $input.all(); 

// 2. Ambil data ITEM BARU (Buat List "kopi, indomie")
// Kita panggil langsung dari node Switch biar aman
const switchData = $('Switch').all(); 

// Gabungin nama barang buat laporan
const currentItemsList = switchData.map(x => x.json.item).join(", ");
// Hitung total belanjaan sesi ini
const currentTotalBatch = switchData.reduce((acc, curr) => acc + (parseInt(curr.json.amount) || 0), 0);

// --- BAGIAN BAWAH INI SAMA KAYAK KEMARIN (JANGAN DIUBAH) ---
const today = DateTime.now().setZone('Asia/Jakarta');
const currentMonth = parseInt(today.toFormat('MM'));
const currentYear = parseInt(today.toFormat('yyyy'));
const INITIAL_LIMIT = 0; 

const cleanNum = (val) => {
  if (!val) return 0;
  const bersih = String(val).replace(/[^0-9]+/g, "");
  return parseInt(bersih) || 0;
};

let totalKeluar = 0;
let totalMasuk = 0;
let categoryMap = {}; 

for (const item of rows) {
  const data = item.json;
  const tglStr = data.Tanggal;

  if (tglStr) {
    const parts = tglStr.split('/');
    // Pastikan format tanggal aman (antisipasi 2/1/2026 atau 02/01/2026)
    if (parts.length >= 3) {
       const rowMonth = parseInt(parts[1]); 
       const rowYear = parseInt(parts[2]);

       if (rowMonth === currentMonth && rowYear === currentYear) {
         const keluar = cleanNum(data.Keluar);
         const masuk = cleanNum(data.Masuk);
         totalKeluar += keluar;
         totalMasuk += masuk;

         if (keluar > 0) {
           const kat = data.Kategori || "Lainnya"; 
           if (!categoryMap[kat]) categoryMap[kat] = 0;
           categoryMap[kat] += keluar;
         }
       }
    }
  }
}

// LOGIKA SISA BUDGET
const currentBudget = INITIAL_LIMIT + totalMasuk;
const sisaBudget = currentBudget - totalKeluar;
const isWarning = sisaBudget < (currentBudget * 0.2);
const statusBudget = sisaBudget < 0 ? "🛑 OVER BUDGET!" : (isWarning ? "⚠️ KRITIS" : "✅ Aman");

// SIAPKAN CHART (Sama kayak kemarin)
const labels = Object.keys(categoryMap); 
const values = Object.values(categoryMap);
const chartConfig = {
  type: 'outlabeledPie',
  data: {
    labels: labels,
    datasets: [{
      data: values,
      backgroundColor: ['#FF6384', '#36A2EB', '#FFCE56', '#4BC0C0', '#9966FF', '#FF9F40']
    }]
  },
  options: {
    plugins: {
      legend: false,
      outlabels: { text: '%l %p', color: 'white', stretch: 35, font: { resizable: true, minSize: 12, maxSize: 18 } }
    }
  }
};
const chartUrl = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(chartConfig))}`;

// RETURN FINAL
return {
  totalKeluar,
  totalMasuk,
  saldoBulanIni: sisaBudget,
  bulan: today.toFormat('MMMM yyyy'),
  limit: currentBudget,
  sisaBudget,
  statusBudget,
  isWarning,
  chartUrl,
  // Data Batch Terbaru
  currentItem: currentItemsList,
  currentAmount: currentTotalBatch
};

