// 1. Ambil semua data & Set Waktu Jakarta
const rows = $input.all();
const now = DateTime.now().setZone('Asia/Jakarta');

// 2. MUNDUR SATU BULAN (Logika Tutup Buku) ⏪
const lastMonthDate = now.minus({ months: 1 }); 

// 🚨 UPDATE 1: Ubah Target jadi ANGKA (Int) biar "01" jadi 1
const targetMonth = parseInt(lastMonthDate.toFormat('MM'));
const targetYear = parseInt(lastMonthDate.toFormat('yyyy'));
const namaBulanLalu = lastMonthDate.toFormat('MMMM yyyy'); 

// 3. Fungsi Pembersih
const cleanNum = (val) => {
  if (!val) return 0;
  const bersih = String(val).replace(/[^0-9]+/g, "");
  return parseInt(bersih) || 0;
};

let totalKeluar = 0;
let totalMasuk = 0;
let categoryMap = {}; 

// 4. Looping & Filter
for (const item of rows) {
  const data = item.json;
  const tglStr = data.Tanggal;

  if (tglStr) {
    const parts = tglStr.split('/');
    // Pastikan format tanggal valid (antisipasi array kosong)
    if (parts.length >= 3) {
        // 🚨 UPDATE 2: Ubah Data Sheet jadi ANGKA juga
        const rowMonth = parseInt(parts[1]);
        const rowYear = parseInt(parts[2]);

        // FILTER: Bandingkan Angka vs Angka (1 === 1) ✅ Aman
        if (rowMonth === targetMonth && rowYear === targetYear) {
          const keluar = cleanNum(data.Keluar);
          const masuk = cleanNum(data.Masuk);

          totalKeluar += keluar;
          totalMasuk += masuk;

          // Grouping Kategori
          if (keluar > 0) {
            // Kita bikin lowercase biar "Makan" dan "makan" jadi satu
            const kat = (data.Kategori || "Lainnya").toLowerCase(); 
            if (!categoryMap[kat]) categoryMap[kat] = 0;
            categoryMap[kat] += keluar;
          }
        }
    }
  }
}

// 5. Hitung Neraca Akhir
const cashFlow = totalMasuk - totalKeluar;
const statusKeuangan = cashFlow >= 0 ? "🤑 SURPLUS (Untung)" : "😭 DEFISIT (Buntung)";

// 6. Bikin Grafik Pie Chart
const labels = Object.keys(categoryMap); 
const values = Object.values(categoryMap);

const chartConfig = {
  type: 'outlabeledPie',
  data: {
    labels: labels,
    datasets: [{
      data: values,
      backgroundColor: ['#FF6384', '#36A2EB', '#FFCE56', '#4BC0C0', '#9966FF', '#FF9F40']
    }]
  },
  options: {
    plugins: {
      legend: false,
      outlabels: {
        text: '%l %p',
        color: 'white',
        stretch: 35,
        font: { resizable: true, minSize: 12, maxSize: 18 }
      }
    }
  }
};

const chartUrl = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(chartConfig))}`;

return {
  bulanLaporan: namaBulanLalu,
  totalMasuk,
  totalKeluar,
  cashFlow,
  statusKeuangan,
  chartUrl
};

