// Ambil semua sampah error yang terkumpul
const errors = $input.all();

let missingPrice = [];
let missingName = [];

for (const err of errors) {
  const data = err.json;

  // Cek kenapa dia gagal
  // Kalau itemnya ada tapi harganya 0/kosong -> Masalah Harga
  if (data.item && (!data.amount || data.amount === 0)) {
    missingPrice.push(data.item);
  } 
  // Kalau itemnya kosong -> Masalah Nama
  else {
    missingName.push("Barang tanpa nama"); // atau ambil raw text kalau ada
  }
}

