// 1. Ambil output mentah dari Gemini
const response = $('HTTP Request').first();
const rawText = response.json.candidates[0].content.parts[0].text;

// 2. Bersihin Markdown
const cleanText = rawText.replace(/```json|```/g, '').trim();

let items = [];

try {
  const parsed = JSON.parse(cleanText);

  // 3. CEK KARDUS: Apakah ini Array (Banyak Barang) atau Object (Satu Barang)?
  if (Array.isArray(parsed)) {
    items = parsed; // Kalau banyak, ambil semua
  } else {
    items = [parsed]; // Kalau satu, bungkus jadi array biar seragam
  }

  // 4. MAP DATA: Standarisasi semua item biar siap masuk Sheet
  return items.map(data => {
    return {
      json: {
        // Samain variablenya dengan input manual (huruf kecil)
        item: data.Item || data.item || "Barang Tak Terbaca",
        amount: data.Amount || data.amount || data.Harga || 0,
        kategori: data.Category || data.category || "Lainnya",

        // Data pelengkap
        tanggal: new Date().toLocaleDateString('id-ID'),
        jam: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }),
        type: "keluar"
      }
    }
  });

} catch (error) {
  return {
    json: {
      error: "Gagal parsing JSON",
      raw: rawText
    }
  };
}
